import React, { useState } from "react";
import logo from "../assets/sorsu-logo.png";

function UserDashboard({
  candidates = [],
  selectedVotes = {},
  setSelectedVotes,
  handleVoteSubmit,
  electionClosed = false,
}) {
  const positions = [...new Set(candidates.map((c) => c.candidacy))];
  const [showModal, setShowModal] = useState(false);

  const openModal = () => {
    if (Object.keys(selectedVotes).length === 0) {
      alert("Please select at least one candidate before voting.");
      return;
    }
    setShowModal(true);
  };

  const confirmVote = () => {
    handleVoteSubmit();
    setShowModal(false);
  };

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        {/* HEADER */}
        <div style={styles.header}>
          <img src={logo} alt="School Logo" style={styles.logo} />
          <div>
            <h2 style={styles.schoolName}>Sorsogon State University</h2>
            <p style={styles.systemText}>Online Voting System</p>
          </div>
        </div>

        <h1 style={styles.title}>Student Election 2026</h1>
        <p style={styles.subtitle}>Select one candidate per position</p>

        {electionClosed && (
          <div style={styles.closedBanner}>Election is Closed</div>
        )}

        {/* POSITIONS */}
        {positions.map((position) => (
          <div key={position} style={styles.positionCard}>
            <h2 style={styles.positionTitle}>{position}</h2>

            {candidates
              .filter((c) => c.candidacy === position)
              .map((candidate) => (
                <label key={candidate._id} style={styles.candidateRow}>
                  <input
                    type="radio"
                    name={position}
                    value={candidate._id}
                    checked={selectedVotes[position] === candidate._id}
                    onChange={() =>
                      setSelectedVotes({
                        ...selectedVotes,
                        [position]: candidate._id,
                      })
                    }
                    disabled={electionClosed}
                  />

                  <div style={styles.candidateInfo}>
                    {candidate.image && (
                      <img
                        src={`http://localhost:5000/uploads/${candidate.image}`}
                        alt={`${candidate.firstName} ${candidate.lastName}`}
                        style={styles.avatar}
                      />
                    )}

                    <div>
                      <div style={styles.candidateName}>
                        {candidate.firstName} {candidate.lastName}
                      </div>

                      <div style={styles.metaText}>
                        {candidate.yearLevel} | {candidate.block}
                      </div>

                      <div style={styles.description}>
                        {candidate.description}
                      </div>
                    </div>
                  </div>
                </label>
              ))}
          </div>
        ))}

        {!electionClosed && positions.length > 0 && (
          <button style={styles.voteButton} onClick={openModal}>
            Cast Vote
          </button>
        )}

        {positions.length === 0 && (
          <p style={{ textAlign: "center", marginTop: 20 }}>
            No candidates available.
          </p>
        )}
      </div>

      {/* ✅ SQUARE CENTER MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <h3 style={{ marginBottom: 15 }}>Confirm Vote</h3>
            <p style={{ marginBottom: 25 }}>
              Are you sure you want to cast your vote? This cannot be changed.
            </p>

            <div style={modalStyles.buttons}>
              <button
                style={modalStyles.cancel}
                onClick={() => setShowModal(false)}
              >
                Cancel
              </button>

              <button style={modalStyles.confirm} onClick={confirmVote}>
                Confirm
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default UserDashboard;

/* =======================
   STYLES (IMPORTANT!)
======================= */

const styles = {
  page: {
    minHeight: "100vh",
    background: "#f4f6f9",
    padding: "30px",
    fontFamily: "Arial, sans-serif",
  },
  container: {
    maxWidth: "900px",
    margin: "auto",
    background: "white",
    padding: "30px",
    borderRadius: "10px",
    boxShadow: "0 5px 15px rgba(0,0,0,0.1)",
  },
  header: {
    display: "flex",
    alignItems: "center",
    gap: "15px",
    marginBottom: "20px",
  },
  logo: {
    width: "60px",
  },
  schoolName: {
    margin: 0,
  },
  systemText: {
    margin: 0,
    color: "gray",
  },
  title: {
    textAlign: "center",
    marginBottom: "5px",
  },
  subtitle: {
    textAlign: "center",
    color: "gray",
    marginBottom: "30px",
  },
  closedBanner: {
    background: "#ff4d4d",
    color: "white",
    padding: "10px",
    textAlign: "center",
    borderRadius: "6px",
    marginBottom: "20px",
  },
  positionCard: {
    border: "1px solid #ddd",
    padding: "15px",
    marginBottom: "20px",
    borderRadius: "8px",
  },
  positionTitle: {
    marginBottom: "10px",
  },
  candidateRow: {
    display: "flex",
    gap: "10px",
    alignItems: "flex-start",
    marginBottom: "10px",
    cursor: "pointer",
  },
  candidateInfo: {
    display: "flex",
    gap: "10px",
  },
  avatar: {
    width: "70px",
    height: "70px",
    objectFit: "cover",
    borderRadius: "8px",
  },
  candidateName: {
    fontWeight: "bold",
  },
  metaText: {
    fontSize: "13px",
    color: "gray",
  },
  description: {
    fontSize: "14px",
    marginTop: "5px",
  },
  voteButton: {
    width: "100%",
    padding: "12px",
    background: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "8px",
    fontSize: "16px",
    cursor: "pointer",
  },
};

const modalStyles = {
  overlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    background: "rgba(0,0,0,0.5)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    background: "white",
    padding: "30px",
    width: "350px",
    borderRadius: "10px",
    textAlign: "center",
    boxShadow: "0 5px 20px rgba(0,0,0,0.3)",
  },
  buttons: {
    display: "flex",
    justifyContent: "space-between",
  },
  cancel: {
    padding: "8px 20px",
    border: "none",
    background: "#ccc",
    borderRadius: "6px",
    cursor: "pointer",
  },
  confirm: {
    padding: "8px 20px",
    border: "none",
    background: "#28a745",
    color: "white",
    borderRadius: "6px",
    cursor: "pointer",
  },
};
